package com.leotechnologies.tests;

import com.leotechnologies.tests.core.SiteConfig;

import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * The audit tests' browser checks: a markup item's pages, each asked once by HTTP (it must answer 2xx at its
 * own address: a redirect to a sign-in page or a bot wall is no page to read) and opened in a browser (AuditBrowser),
 * where
 * the crawler's own reader (src/test/resources/audit/reader.js, written by Suite Builder) reads it again. Open while
 * the
 * reader names the item on any page checked; fixed when it names it on none and every page was read, said as "not seen
 * on
 * the pages checked (3 of 12)" when the crawl saw it on more; otherwise "could not check", never fixed. The reader is
 * given the
 * read and what the item said (slice 5: the shared words, a threshold); a read with nothing said is one it judges
 * itself, open
 * while it names anything.
 */
final class AuditPages {
    private static String reader;

    private AuditPages() {}

    /** What the check saw of one item on its pages: open, fixed or cannot, and in words. */
    static String[] seen(String read, String said, List<String> pages, int of) {
        List<String> open = new ArrayList<>();
        List<String> cannot = new ArrayList<>();
        for (String path : pages) {
            String[] one = page(read, said, path);
            if (one[0].equals("open")) open.add(one[1]);
            else if (one[0].equals("cannot")) cannot.add(one[1]);
        }
        if (!open.isEmpty()) return new String[] {"open", String.join("; ", open)};
        if (!cannot.isEmpty()) return new String[] {"cannot", String.join("; ", cannot)};
        String checked = String.join(", ", pages);
        return new String[] {"fixed", of > pages.size() ? "not seen on the pages checked (" + pages.size() + " of "
                + of + ": " + checked + ")" : "not seen on " + checked};
    }

    /** One page: asked, opened and read; open, fixed or cannot for it. */
    private static String[] page(String read, String said, String path) {
        Read one = read(path, said.isEmpty() ? read : read + " " + said);
        if (one.cannot() != null) return new String[] {"cannot", one.cannot()};
        List<String> named = one.named();
        return switch (read) {
            case "lang" -> named.isEmpty() ? new String[] {"open", path
                    + " has no lang on <html>"} : new String[] {"fixed", path + " says lang " + named.get(0)};
            case "h1" -> named.size() == 1 ? new String[] {"fixed", path
                    + " has one main heading"} : new String[] {"open", path + " has " + named.size()
                    + " main headings (h1) with words"};
            case "errors" -> named.stream()
                    .anyMatch(thrown -> says(thrown, said)) ? new String[] {"open", "seen on "
                    + path} : new String[] {"fixed", "not seen on " + path};
            // A read the reader judges itself (slice 5: no title, no description, a viewport that stops zooming): open
            // while it names anything.
            default -> said.isEmpty()
                    ? (named.isEmpty() ? new String[] {"fixed", "not seen on " + path} : new String[] {"open", path
                            + ": " + String.join("; ", named)})
                    : named.contains(said) ? new String[] {"open", "seen on " + path} : new String[] {"fixed",
                            "not seen on " + path};
        };
    }

    /** What the reader named on one page, or why it could not be read (then named is empty). */
    private record Read(List<String> named, String cannot) {}

    /** One page asked by HTTP once (it must answer 2xx at its own address), opened in the browser and read. */
    private static Read read(String path, String asked) {
        HttpResponse<Void> answer;
        try {
            answer = AuditChecks.ask(path);
        } catch (IOException e) {
            return new Read(List.of(), path + " gave no answer (" + e.getClass().getSimpleName() + ")");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return new Read(List.of(), "the run was stopped");
        }
        int status = answer.statusCode();
        if (status < 200 || status >= 300) {
            String to = answer.headers().firstValue("location").orElse("");
            return new Read(List.of(), path + " answered " + status + (to.isEmpty() ? "" : " to " + to)
                    + ", no page to read");
        }
        String url = SiteConfig.url(path);
        List<String> found;
        try {
            found = AuditBrowser.read(url, reader(), asked);
        } catch (RuntimeException e) {
            return new Read(List.of(), "the browser could not read " + path + ": " + String.valueOf(e.getMessage())
                    .lines().findFirst().orElse(""));
        }
        String at = found.isEmpty() ? "" : found.get(0);
        if (!URI.create(at).getPath().equals(URI.create(url).getPath())) return new Read(List.of(), path
                + " sent the browser to " + at);
        return new Read(found.subList(1, found.size()), null);
    }

    /**
     * Whether an error the browser heard is the one an item said (SITE-21): the item's words (the crawl's: an error's
     * message, its
     * first line, 120 characters, with markupKey's masks) found in what the browser reported, each mask (*) matching
     * anything. The
     * browser's report may put the error's name or "Uncaught" first, or its stack after: matched within, never whole,
     * so an error
     * still thrown is never read as gone.
     */
    static boolean says(String thrown, String said) {
        List<String> parts = pieces(said, '*', true);
        for (String line : pieces(thrown, '\n', false)) {
            // Each part of the words in order on one line, each found as early as it can be; a mask (*) is anything
            // between.
            int end = 0;
            boolean all = true;
            for (String part : parts) {
                int found = line.indexOf(part, end);
                if (found < 0) {
                    all = false;
                    break;
                }
                end = found + part.length();
            }
            if (all) return true;
        }
        return false;
    }

    /**
     * The pieces of a text between each of a character: every one when `all`, else those at its end that are empty left
     * out
     * (none of an empty text's but itself).
     */
    static List<String> pieces(String text, char between, boolean all) {
        List<String> out = new ArrayList<>();
        int from = 0;
        for (int at = text.indexOf(between); at >= 0; at = text.indexOf(between, from)) {
            out.add(text.substring(from, at));
            from = at + 1;
        }
        out.add(text.substring(from));
        if (!all && out.size() > 1) while (!out.isEmpty() && out.get(out.size() - 1).isEmpty()) out.remove(
                out.size() - 1);
        return out;
    }

    /**
     * A page's canonical links (SITE-12), as the browser reads them (never the page's text by a pattern), each
     * judged by the crawl's rule (AuditChecks.canonicalSeen): open while one names another site, or an address of the
     * site that answers
     * 400 or more or redirects; fixed when it names none, or each names one that answers; a page that cannot be read
     * could not check.
     */
    static String[] canonical(String path) {
        Read one = read(path, "canonical");
        if (one.cannot() != null) return new String[] {"cannot", one.cannot()};
        if (one.named().isEmpty()) return new String[] {"fixed", "names no canonical address"};
        List<String[]> each = new ArrayList<>();
        for (String href : one.named()) each.add(AuditChecks.canonicalSeen(path, href));
        for (String kind : List.of("open", "cannot")) {
            List<String> words = each.stream().filter(s -> s[0].equals(kind)).map(s -> s[1]).toList();
            if (!words.isEmpty()) return new String[] {kind, String.join("; ", words)};
        }
        return new String[] {"fixed", String.join("; ", each.stream().map(s -> s[1]).toList())};
    }

    /** The crawler's reader, as Suite Builder wrote it into the suite. */
    private static synchronized String reader() {
        if (reader != null) return reader;
        try (InputStream in = AuditPages.class.getResourceAsStream("/audit/reader.js")) {
            if (in == null) throw new IllegalStateException(
                    "src/test/resources/audit/reader.js is missing: rebuild the suite");
            reader = new String(in.readAllBytes(), StandardCharsets.UTF_8);
            return reader;
        } catch (IOException e) {
            throw new IllegalStateException("src/test/resources/audit/reader.js could not be read: " + e.getMessage(),
                    e);
        }
    }
}
